package com.eccraft.techtainark;
import com.eccraft.Eccraft;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.resources.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.core.component.DataComponents;
public final class ArkEquipment{
 private static Item register(String id,boolean hammer){var key=ResourceKey.create(Registries.ITEM,Eccraft.id(id));var p=new Item.Properties().setId(key).component(DataComponents.LORE,com.eccraft.item.ItemDescriptions.lore(id));if(hammer)p.rarity(Rarity.EPIC).durability(500).enchantable(15).repairable(Items.BREEZE_ROD).component(DataComponents.TOOL,MaceItem.createToolProperties()).component(DataComponents.WEAPON,new net.minecraft.world.item.component.Weapon(1)).attributes(net.minecraft.world.item.component.ItemAttributeModifiers.builder().add(Attributes.ATTACK_DAMAGE,new AttributeModifier(Item.BASE_ATTACK_DAMAGE_ID,1,AttributeModifier.Operation.ADD_VALUE),EquipmentSlotGroup.MAINHAND).add(Attributes.ATTACK_SPEED,new AttributeModifier(Item.BASE_ATTACK_SPEED_ID,-2.4,AttributeModifier.Operation.ADD_VALUE),EquipmentSlotGroup.MAINHAND).build());return Registry.register(BuiltInRegistries.ITEM,key,hammer?new FlyingHammerItem(p):new Item(p));}
 public static final Item FRAGMENT=register("beating_fragment",false),HEART=register("beating_heart",false),DUST=register("magic_dust",false),HAMMER=register("flying_trapeze_hammer",true);
 public static void register(){com.eccraft.effect.DizzinessEffect.register();}private ArkEquipment(){}
}